@test("valid values are stored")
def _():
    p = Product("pen", 1.5, 10)
    assert (p.name, p.price, p.qty) == ("pen", 1.5, 10)

@test("wrong types raise TypeError naming the attribute")
def _():
    e = raises(TypeError, Product, "pen", "cheap", 1)
    assert "price" in str(e), f"message: {e}"
    e = raises(TypeError, Product, 42, 1.0, 1)
    assert "name" in str(e), f"message: {e}"

@test("values below min_value raise ValueError naming the attribute")
def _():
    e = raises(ValueError, Product, "pen", -1.0, 1)
    assert "price" in str(e), f"message: {e}"
    p = Product("pen", 1.0, 1)
    e = raises(ValueError, setattr, p, "qty", -3)
    assert "qty" in str(e) and p.qty == 1

@test("bool is rejected for an int field")
def _():
    raises(TypeError, Product, "pen", 1.0, True)

@test("an int is accepted and converted for a float field")
def _():
    p = Product("pen", 3, 1)
    assert p.price == 3.0 and type(p.price) is float, f"price = {p.price!r}"

@test("each instance keeps its own values")
def _():
    a, b = Product("a", 1.0, 1), Product("b", 2.0, 2)
    assert (a.name, a.price, b.name, b.price) == ("a", 1.0, "b", 2.0)

@test("an unset field raises AttributeError")
def _():
    p = Product.__new__(Product)  # skip __init__
    raises(AttributeError, getattr, p, "price")

@test("class access returns the descriptor")
def _():
    assert isinstance(Product.price, Typed)

@test("the name comes from __set_name__")
def _():
    class Point:
        x = Typed(int)
    pt = Point()
    e = raises(TypeError, setattr, pt, "x", "1")
    assert "x" in str(e), f"message: {e}"

