class Typed:
    """A data descriptor that type-checks (and optionally range-checks) an attribute."""

    def __init__(self, kind, *, min_value=None):
        self.kind = kind
        self.min_value = min_value
        self.name = None

    def __set_name__(self, owner, name):
        self.name = name  # called once, when the owning class is created

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self  # accessed on the class
        try:
            # Same key as the attribute: safe, because a data descriptor (one with
            # __set__) takes priority over the instance __dict__ on lookup.
            return obj.__dict__[self.name]
        except KeyError:
            raise AttributeError(f"{self.name} is not set") from None

    def __set__(self, obj, value):
        if self.kind is float and type(value) is int:
            value = float(value)
        if (isinstance(value, bool) and self.kind is not bool) or not isinstance(value, self.kind):
            raise TypeError(f"{self.name} must be {self.kind.__name__}, got {type(value).__name__}")
        if self.min_value is not None and value < self.min_value:
            raise ValueError(f"{self.name} must be >= {self.min_value}, got {value}")
        obj.__dict__[self.name] = value


class Product:
    name = Typed(str)
    price = Typed(float, min_value=0)
    qty = Typed(int, min_value=0)

    def __init__(self, name, price, qty):
        self.name = name
        self.price = price
        self.qty = qty
